    ['no_transaction' => '000002', 'name' => 'Anonymous', 'amount' => '$10000', 'date' => 'Jan 01, 2020 00:00:00', 'is_active' => true, 'user_id' => 1, 'type_id' => 2],
    ['no_transaction' => '000003', 'name' => 'Wedding', 'amount' => '$40000', 'date' => null, 'is_active' => false, 'user_id' => 1, 'type_id' => 3],
]
