function processTransactions(array $transactions): array {
    $processedTransactions = [];
    foreach ($transactions as $transaction) {
        $processedTransaction = $transaction;
        // Replace '<NAME>' with 'Anonymous'
        $processedTransaction['name'] = ($transaction['name'] === '<NAME>') ? 'Anonymous' : $transaction['name'];
        // Convert 'amount' to string representation with currency symbol
        $processedTransaction['amount'] = '$' . number_format($transaction['amount']);
        // Convert 'date' to human-readable format
        if ($transaction['date'] !== null) {
            $processedTransaction['date'] = date('M d, Y H:i:s', strtotime($transaction['date']));
        }
        // Replace 'is_active' with boolean value
        $processedTransaction['is_active'] = (bool) $transaction['is_active'];
        $processedTransactions[] = $processedTransaction;
    }
