### Solution:
```rust
fn median(list: &Vec<i32>) -> f32 {
    let mut temp = list.clone();
    temp.sort();
    if list.len() % 2 == 0 {
        let i = list.len() / 2;
        let n = temp[i] as f32;
        let d = temp[i - 1] as f32;
        (n + d) / 2.0
    } else {
        temp[(list.len() - 1) / 2] as f32
    }
}
