### Solution:
```swift
// Complete the code snippet and implement the Sampling collection type

struct Sampling<Selection>: RandomAccessCollection where Selection: RandomAccessCollection {
    let selection: Selection

    init(selection: Selection) {
        self.selection = selection
    }

    var startIndex: Selection.Index {
        return selection.startIndex
    }

    var endIndex: Selection.Index {
        return selection.endIndex
    }

    func index(after i: Selection.Index) -> Selection.Index {
        return selection.index(after: i)
    }

    func index(before i: Selection.Index) -> Selection.Index {
        return selection.index(before: i)
    }

    subscript(position: Selection.Index) -> Selection.Element {
        return selection[position]
    }
}

// Example usage
let numbers = [1, 2, 3, 4, 5]
let sampling = Sampling(selection: numbers)

