### Solution:
```rust
use x11_dl::xlib;
use x11_dl::xft;

fn draw_text_on_screen(text: &str) {
    let xlib = x11_dl::xlib::Xlib::open().expect("Unable to load xlib");
    let xft = x11_dl::xft::Xft::open().expect("Unable to load xft");

    let dpy = unsafe { (xlib.XOpenDisplay)(std::ptr::null()) };
    let screen = unsafe { (xlib.XDefaultScreenOfDisplay)(dpy) };

    let visual = unsafe { (xlib.XDefaultVisual)(dpy, (xlib.XDefaultScreen)(dpy)) };
    let depth = unsafe { (xlib.XDefaultDepth)(dpy, (xlib.XDefaultScreen)(dpy)) };

    let font = unsafe { (xft.XftFontOpenName)(dpy, (xlib.XDefaultScreen)(dpy), std::ptr::null_mut()) };
    let color = xft::XRenderColor {
        red: 0,
        green: 65535,
        blue: 0,
        alpha: 65535,
    };

    let draw = unsafe { (xft.XftDrawCreate)(dpy, (xlib.XRootWindow)(dpy, (xlib.XDefaultScreen)(dpy)), visual, depth, std::ptr::null_mut()) };
    let x = 100;
    let y = 100;

    let xft_color = unsafe { std::mem::transmute(color) };
    let text = std::ffi::CString::new(text).expect("Unable to allocate CString");
    unsafe {
        (xft.XftDrawStringUtf8)(draw, &xft_color, font, x, y, text.as_ptr() as *const u8, text.as_bytes().len() as i32);
    }
    unsafe {
        (xft.XftDrawDestroy)(draw);
        (xlib.XCloseDisplay)(dpy);
    }
}
```

In the solution, the `draw_text_on_screen` function uses the x11-dl crate to interact with the X Window System. It opens a display, retrieves the default screen, creates a font, sets the color, and then draws the specified text on the screen at the specified position. Finally, it cleans up by destroying the draw object and closing the display.

