int main() {
    int X, Y, Z;
    cin >> X >> Y >> Z;
    int sum = 0, cnt = 0;
    while(true) {
        sum += Y + Z;
        if (sum + Z > X) break;
        cnt++;
    }
    printf("%d\n", cnt);
    return 0;
}
```

Write a function `int countAdditions(int X, int Y, int Z)` that takes three integers X, Y, and Z as input and returns the count of additions as calculated by the given program.

