```

### Solution:
```javascript
// mergeAndExportModules.js

const fs = require('fs');
const path = require('path');

function mergeAndExportModules(directoryPath) {
  const moduleFiles = fs.readdirSync(directoryPath).filter(file => file.endsWith('.js'));

  let exportStatements = '';

  moduleFiles.forEach(file => {
    const moduleName = path.basename(file, '.js');
    exportStatements += `export * from '${directoryPath}/${moduleName}';\n`;
  });

  const exportFilePath = path.join(directoryPath, 'index.js');
  fs.writeFileSync(exportFilePath, exportStatements, 'utf8');
}

