### Solution:
```rust
impl TextFormatter {
    fn new(width: usize) -> TextFormatter {
        TextFormatter { x: 0, width }
    }

    fn newline(&mut self) {
        self.x = 0;  // Reset the cursor position to the beginning of the new line
    }

    fn forward(&mut self) {
        self.x += 1;  // Move the cursor forward by one position

        if self.x >= self.width {
            self.newline();  // Wrap to the next line if the cursor reaches the maximum width
        }
    }
}
```
