function processExerciseData($conexao, $sql) {
    $result = mysqli_query($conexao, $sql);
    $exercises = mysqli_fetch_all($result, MYSQLI_ASSOC);

    $totalExercises = count($exercises);

    $totalDuration = 0;
    $longestExercise = null;

    foreach ($exercises as $exercise) {
