### Problem:
You are tasked with creating a program that processes a Swift Package manifest file and extracts specific information from it. The Swift Package manifest file, typically named `Package.swift`, is used to define the package's name, supported platforms, products, dependencies, and other metadata. Your program should be able to parse the manifest file and extract the platforms and products defined within it.

Write a function or method that takes the contents of a Swift Package manifest file as input and returns the supported platforms and products defined in the file. The input will be a string containing the contents of the `Package.swift` file. The output should be a dictionary containing the supported platforms and an array of products defined in the manifest file.

Example:
Input:
```
let package = Package(
    name: "MessageInputBar",
    platforms: [
        .iOS(.v13)
    ],
    products: [
        .library(
            name: "MessageInputBar",
            targets: ["MessageInputBar"]
        )
    ]
)
```
Output:
```
{
    "platforms": ["iOS(v13)"],
    "products": ["MessageInputBar"]
}
```

### Solution:
```swift
func parsePackageManifest(_ manifestContent: String) -> [String: Any] {
    var result: [String: Any] = [:]

    if let platformsRange = manifestContent.range(of: "platforms: [") {
        let platformsSubstring = manifestContent[platformsRange.upperBound...]
        if let platformsEndIndex = platformsSubstring.firstIndex(of: "]") {
            let platformsContent = platformsSubstring[..<platformsEndIndex]
            let platforms = platformsContent.components(separatedBy: .newlines).filter { !$0.trimmingCharacters(in: .whitespaces).isEmpty }
            result["platforms"] = platforms
        }
    }

    if let productsRange = manifestContent.range(of: "products: [") {
        let productsSubstring = manifestContent[productsRange.upperBound...]
        if let productsEndIndex = productsSubstring.firstIndex(of: "]") {
            let productsContent = productsSubstring[..<productsEndIndex]
            let products = productsContent.components(separatedBy: .newlines).filter { !$0.trimmingCharacters(in: .whitespaces).isEmpty }
                .map { $0.trimmingCharacters(in: .whitespaces) }
                .filter { $0.hasPrefix(".library") }
                .compactMap { $0.components(separatedBy: .whitespaces).last?.replacingOccurrences(of: "\"", with: "") }
            result["products"] = products
        }
    }

    return result
}

// Example usage
let manifestContent = """
let package = Package(
    name: "MessageInputBar",
    platforms: [
        .iOS(.v13)
    ],
    products: [
        .library(
            name: "MessageInputBar",
            targets: ["MessageInputBar"]
        )
    ]
)
"""
let parsedManifest = parsePackageManifest(manifestContent)
print(parsedManifest)  // Output: ["platforms": ["    .iOS(.v13)"], "products": ["MessageInputBar"]]
```

