### Solution:
```cpp
#include <iostream>
#include <sdsl/int_vector.hpp>
#include <fstream>

size_t processFiles(int argc, char* argv[]) {
  size_t totalSize = 0;
  for(int i = optind; i < argc; i++) {
    std::string base_name = argv[i];
    std::cout << "File: " << base_name << std::endl;
    sdsl::int_vector<8> text;
    sdsl::cache_config config;
    size_t size = 0;

    std::ifstream file(base_name, std::ios::binary);
    if (file) {
      file.seekg(0, std::ios::end);
      size = file.tellg();
      file.seekg(0, std::ios::beg);

      text.resize(size);
      file.read((char*)text.data(), size);
      file.close();

      totalSize += size;
    } else {
      std::cerr << "Error: Unable to open file " << base_name << std::endl;
    }
  }
  return totalSize;
}
```

