### Solution:
```rust
use multihash::{Code, MultihashDigest, MultihashGeneric, Sha2_256};
use cid::Cid;
use std::convert::TryInto;

fn sha256_to_cid(hash: &str) -> Result<Cid, &'static str> {
    if hash.len() != 64 {
        return Err("Input hash must be 32 bytes long");
    }

    let hash_bytes = match hex::decode(hash) {
        Ok(bytes) => bytes,
        Err(_) => return Err("Invalid hex encoding"),
    };

    let multihash = MultihashGeneric::wrap(Sha2_256::digest(&hash_bytes))
        .map_err(|_| "Failed to create multihash")?;

    let cid = Cid::new_v1(0x55, multihash.to_bytes().try_into().unwrap());
    Ok(cid)
}
```

