    }

    // Decrement the counter by the given positive value if it is in the .down state
    mutating func decrement(by value: Int) {
        // Add your implementation here
    }

    // Return true if the counter is in the .down state and its value is less than or equal to 0, false otherwise
    var isCompleted: Bool {
        // Add your implementation here
    }
}

// Test cases
