```

### Solution:
```swift
enum UpDown {
    case up(Int)
    case down(Int)
}

struct UpDownCounter {
    var counter: UpDown

    mutating func increment(by value: Int) {
        if case var .up(currentValue) = counter {
            currentValue += value
            counter = .up(currentValue)
        }
    }

    mutating func decrement(by value: Int) {
        if case var .down(currentValue) = counter {
            currentValue -= value
            counter = .down(currentValue)
        }
    }

    var isCompleted: Bool {
        if case let .down(value) = counter {
            return value <= 0
        }
        return false
    }
}

// Test cases
var upCounter = UpDownCounter(counter: .up(5))
upCounter.increment(by: 3)
print(upCounter.isCompleted) // Should print: false

var downCounter = UpDownCounter(counter: .down(10))
downCounter.decrement(by: 5)
print(downCounter.isCompleted) // Should print: true
```

In the solution, the `UpDownCounter` struct is implemented with methods to increment and decrement the counter based on its current state, as well as a property `isCompleted` to check if the counter is in the `.down` state and its value is less than or equal to 0. The test cases demonstrate the expected behavior of the `UpDownCounter` implementation.

